import type { components } from './schema.d'

// Compile-time contract check: if the backend schema drops or renames a field, `npm run typecheck` fails here
// (the generated file is the source of truth, regenerated by `npm run gen:api`).
type CardEvent = components['schemas']['CardEvent']
type DoneEvent = components['schemas']['DoneEvent']

describe('generated API contract', () => {
  it('exposes the discriminated event and card unions', () => {
    const done: DoneEvent = { event: 'done', v: 1, seq: 9, t: 5120, status: 'complete', message_id: 'm1' }
    const card: CardEvent['payload']['type'] = 'precedents'
    expect(done.status).toBe('complete')
    expect(card).toBe('precedents')
  })
})
